-- Run in a NEW Supabase project using SQL Editor. Existing application tables are not dropped.
begin;
grant usage on schema public to anon, authenticated;

create table public.countries (
  "countryID" bigint generated by default as identity primary key,
  "countryName" text not null, capital text not null default '',
  population bigint not null default 0, "languageName" text not null default ''
);
create table public.genres (
  "genreID" bigint generated by default as identity primary key,
  "genreName" text not null unique, description text not null default ''
);
create table public.directors (
  "directorID" bigint generated by default as identity primary key,
  "fullName" text not null, "birthDate" date,
  "countryID" bigint references public.countries on delete restrict,
  "experienceYears" integer not null default 0, "awardsCount" integer not null default 0
);
create table public.actors (
  "actorID" bigint generated by default as identity primary key,
  "fullName" text not null, age integer not null default 0,
  gender text not null default '', "countryID" bigint references public.countries on delete restrict,
  "oscarAwards" integer not null default 0, salary numeric not null default 0,
  "photoUrl" text not null default '' check ("photoUrl" = '' or "photoUrl" ~ '^https://')
);
create table public.movies (
  "movieID" bigint generated by default as identity primary key,
  title text not null check (length(title) between 1 and 200),
  description text not null default '', "releaseYear" integer not null,
  "durationMinutes" integer not null default 0,
  "countryID" bigint references public.countries on delete restrict,
  "directorID" bigint references public.directors on delete restrict,
  "genreID" bigint references public.genres on delete restrict,
  "mainActorID" bigint references public.actors on delete set null,
  budget numeric not null default 0, "boxOffice" numeric not null default 0,
  rating numeric not null default 0 check (rating between 0 and 10),
  "discountPercent" integer not null default 0 check ("discountPercent" between 0 and 100),
  "languageName" text not null default 'English', "ageRestriction" text not null default '',
  "productionCompany" text not null default '', "subtitleAvailable" boolean not null default false,
  "is3D" boolean not null default false,
  "posterUrl" text not null default '' check ("posterUrl" = '' or "posterUrl" ~ '^https://'),
  "trailerUrl" text not null default '',
  "watchUrl" text not null default '' check ("watchUrl" = '' or "watchUrl" ~ '^https://'),
  "licenseUrl" text not null default '' check ("licenseUrl" = '' or "licenseUrl" ~ '^https://'),
  attribution text not null default '', "isFree" boolean not null default false
);
create table public.movieactors (
  "movieActorID" bigint generated by default as identity primary key,
  "movieID" bigint not null references public.movies on delete cascade,
  "actorID" bigint not null references public.actors on delete cascade,
  "roleName" text not null default '', "screenTimeMinutes" integer not null default 0,
  unique ("movieID", "actorID")
);
create table public.ratings (
  "ratingID" bigint generated by default as identity primary key,
  "movieID" bigint not null unique references public.movies on delete cascade,
  "imDbRating" numeric, "rottenTomatoes" integer, metacritic integer,
  "reviewCount" integer not null default 0
);
create table public.discounts (
  "discountID" bigint generated by default as identity primary key,
  "movieID" bigint not null references public.movies on delete cascade,
  "discountName" text not null, "discountPercent" integer not null default 0,
  "startDate" timestamptz not null default now(), "endDate" timestamptz not null default now()
);
create table public.boxoffice (
  "boxOfficeID" bigint generated by default as identity primary key,
  "movieID" bigint not null unique references public.movies on delete cascade,
  "openingWeekend" numeric not null default 0, "worldwideGross" numeric not null default 0,
  "ticketsSold" bigint not null default 0
);
create table public.profiles (
  "userID" uuid primary key references auth.users(id) on delete cascade,
  username text not null check (username ~ '^[A-Za-z0-9_-]{3,40}$'),
  "registrationDate" timestamptz not null default now()
);
create unique index profiles_username_unique on public.profiles (lower(username));
create table public.user_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null check (role = 'admin')
);
create table public.reviews (
  "reviewID" bigint generated by default as identity primary key,
  "userID" uuid not null default auth.uid() references public.profiles on delete cascade,
  "movieID" bigint not null references public.movies on delete cascade,
  "commentText" text not null check (length(trim("commentText")) between 1 and 2000),
  "userRating" numeric not null check ("userRating" between 1 and 10),
  "reviewDate" timestamptz not null default now()
);
create table public.favorites (
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  movie_id bigint not null references public.movies on delete cascade,
  created_at timestamptz not null default now(), primary key (user_id, movie_id)
);
create index reviews_movie_idx on public.reviews ("movieID");
create index reviews_user_idx on public.reviews ("userID");
create index movies_genre_idx on public.movies ("genreID");

create function public.is_admin() returns boolean
language sql stable security definer set search_path = ''
as $$ select exists(select 1 from public.user_roles where user_id = (select auth.uid()) and role = 'admin'); $$;
revoke all on function public.is_admin() from public, anon;
grant execute on function public.is_admin() to authenticated;

-- The trigger copies only the username, never a role supplied by the browser.
create function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles ("userID", username)
  values (new.id, coalesce(nullif(trim(new.raw_user_meta_data->>'username'), ''), 'user-' || replace(new.id::text, '-', '')));
  return new;
end; $$;
revoke all on function public.handle_new_user() from public, anon, authenticated;
create trigger cinemax_new_user after insert on auth.users
for each row execute procedure public.handle_new_user();

do $$ declare t text; begin
  foreach t in array array['countries','genres','directors','actors','movies','movieactors','ratings','discounts','boxoffice'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to anon, authenticated', t);
    execute format('grant insert, update, delete on public.%I to authenticated', t);
    execute format('create policy catalog_read on public.%I for select to anon, authenticated using (true)', t);
    execute format('create policy catalog_insert on public.%I for insert to authenticated with check ((select public.is_admin()))', t);
    execute format('create policy catalog_update on public.%I for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()))', t);
    execute format('create policy catalog_delete on public.%I for delete to authenticated using ((select public.is_admin()))', t);
  end loop;
end; $$;
grant usage, select on all sequences in schema public to authenticated;

alter table public.profiles enable row level security;
alter table public.user_roles enable row level security;
alter table public.reviews enable row level security;
alter table public.favorites enable row level security;
revoke all on public.profiles, public.user_roles, public.reviews, public.favorites from anon, authenticated;
grant select on public.profiles, public.reviews to anon, authenticated;
grant insert, delete on public.reviews to authenticated;
grant select, insert, delete on public.favorites to authenticated;
create policy profiles_read on public.profiles for select to anon, authenticated using (true);
-- Roles are managed only by the project owner using SQL Editor.
create policy reviews_read on public.reviews for select to anon, authenticated using (true);
create policy reviews_insert on public.reviews for insert to authenticated with check ("userID" = (select auth.uid()));
create policy reviews_delete on public.reviews for delete to authenticated using ("userID" = (select auth.uid()) or (select public.is_admin()));
create policy favorites_read on public.favorites for select to authenticated using (user_id = (select auth.uid()));
create policy favorites_insert on public.favorites for insert to authenticated with check (user_id = (select auth.uid()));
create policy favorites_delete on public.favorites for delete to authenticated using (user_id = (select auth.uid()));

create function public.admin_users() returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'Administrator access required' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('userID', p."userID", 'username', p.username,
    'email', u.email, 'registrationDate', p."registrationDate", 'reviewCount',
    (select count(*) from public.reviews r where r."userID" = p."userID")))
    from public.profiles p join auth.users u on u.id = p."userID"), '[]'::jsonb);
end; $$;
create function public.admin_delete_user(target uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'Administrator access required' using errcode = '42501'; end if;
  if target = auth.uid() then raise exception 'Cannot delete your own account here'; end if;
  delete from auth.users where id = target;
end; $$;
create function public.admin_summary() returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'Administrator access required' using errcode = '42501'; end if;
  return jsonb_build_object('users',(select count(*) from public.profiles), 'countries',(select count(*) from public.countries),
    'genres',(select count(*) from public.genres), 'directors',(select count(*) from public.directors),
    'actors',(select count(*) from public.actors), 'movies',(select count(*) from public.movies),
    'movieActors',(select count(*) from public.movieactors), 'reviews',(select count(*) from public.reviews),
    'ratings',(select count(*) from public.ratings), 'discounts',(select count(*) from public.discounts),
    'boxOfficeRecords',(select count(*) from public.boxoffice));
end; $$;
revoke all on function public.admin_users(), public.admin_delete_user(uuid), public.admin_summary() from public, anon;
grant execute on function public.admin_users(), public.admin_delete_user(uuid), public.admin_summary() to authenticated;

-- Small public poster bucket: authenticated administrators upload; everyone can read.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('posters','posters',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
create policy posters_insert on storage.objects for insert to authenticated
with check (bucket_id = 'posters' and (select public.is_admin()));
create policy posters_update on storage.objects for update to authenticated
using (bucket_id = 'posters' and (select public.is_admin()))
with check (bucket_id = 'posters' and (select public.is_admin()));
create policy posters_delete on storage.objects for delete to authenticated
using (bucket_id = 'posters' and (select public.is_admin()));
commit;
